#include <iostream>
#include <print>
#include <span>
#include <vector>

long long sum(std::span<const int> values) {
    long long total = 0;
    for (int x : values) {
        total += x;
    }
    return total;
}

int main() {
    std::size_t n;
    std::cin >> n;
    std::vector<int> values(n);
    for (int &x : values) {
        std::cin >> x;
    }
    std::span<const int> all = values;
    long long left = sum(all.first(n / 2));
    long long right = sum(all.last(n / 2));
    std::println("левая {}, правая {}", left, right);
    if (left > right) {
        std::println("левая больше");
    } else if (right > left) {
        std::println("правая больше");
    } else {
        std::println("поровну");
    }
    return 0;
}

