        total += x;
    }
    return total;
}

int main() {
    std::size_t n, k;
    std::cin >> n >> k;
    std::vector<int> values(n);
    for (int &x : values) {
        std::cin >> x;
    }
    if (k > n) {
        std::println("окно больше данных");
        return 0;
    }
    std::span<const int> all = values;
